// Join surviving sides, respecting the actual matching and local degree capacity.
use std::{env,fs};
fn main(){let arg:Vec<_>=env::args().collect();let inp=fs::read_to_string(&arg[1]).unwrap();let mut it=inp.split_whitespace().map(|s|s.parse::<u32>().unwrap());assert_eq!(it.next(),Some(26));let a:Vec<_>=it.take(26).collect();let txt=fs::read_to_string(&arg[2]).unwrap();let sides:Vec<Vec<u32>>=txt.lines().map(|l|l.split_whitespace().map(|s|s.parse().unwrap()).collect()).collect();let anchored=arg.get(3).is_some_and(|s|s=="anchor25");let rgroup=if anchored{sides.iter().filter(|r|r.iter().all(|s|s>>25&1==0)&&r.iter().filter(|s|*s>>22&1!=0).count()>=2).cloned().collect()}else{Vec::new()};let mut joined=0;let mut cap=0;let mut single=0;for(i,l)in sides.iter().enumerate(){if anchored&&l.iter().filter(|s|*s>>25&1!=0).count()<2{continue}for r in if anchored{&rgroup[..]}else{&sides[..i]}{if l.iter().any(|v|r.contains(v)){continue}for p in [[0,1,2],[0,2,1],[1,0,2],[1,2,0],[2,0,1],[2,1,0]]{if (0..3).any(|j|l[j]&r[p[j]]!=0){continue}joined+=1;let e=[l[0],l[1],l[2],r[p[0]],r[p[1]],r[p[2]]];let mut ones=0;let mut req=[0i32;26];let mut valid=true;for v in 0..26{let need=9-(a[v].count_ones()+e.iter().map(|s|s>>v&1).sum::<u32>())as i32;if !(1..=6).contains(&need){valid=false;break}req[v]=need;if need==1{ones|=1u32<<v}}if !valid{continue}if (0..26).any(|v|(0..v).any(|w|a[v]>>w&1!=0&&req[v]+req[w]>6)){continue}cap+=1;if (0..8).any(|m|{let mut u=0;for j in 0..3{u|=e[j+3*((m>>j)&1)]}(ones&!u).count_ones()>6}){continue}single+=1;println!("{} {} {} {} {} {}",e[0],e[1],e[2],e[3],e[4],e[5])}}}eprintln!("matched {joined} capacity {cap} singleton {single}");}
